import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import { webkit } from 'playwright';
const BASE='https://yo666ha-boop.github.io/-/shogi-v21528', CLOUD='https://htvfcdktdjtyoyzrohji.supabase.co/functions/v1/shogi-save';
