async function seed(ctx,deviceId){await ctx.addInitScript(({deviceId,CLOUD})=>{localStorage.setItem('aiShogiCloudConfigV1',JSON.stringify({syncKey:'',deviceId,api:CLOUD,enabled:false}));localStorage.setItem('aiShogiCloudMetaV1',JSON.stringify({revision:0,lastSyncedSavedAt:0,pending:false,lastError:'',updatedAt:Date.now()}));localStorage.removeItem('aiShogiGameSaveV1');window.addEventListener('unhandledrejection',e=>console.log('DIAG_UNHANDLED_REJECTION',String(e.reason?.stack||e.reason||'')))},{deviceId,CLOUD})}
